arguments.rule_content:
{
  "title": "Detect Nmap Scan Followed by Lateral Movement",
  "id": "sigma-2026-0419-nmap-lateral",
  "description": "Detects a pattern where an external IP performs an Nmap scan and then a successful internal authentication indicating possible lateral movement.",
  "status": "experimental",
  "author": "SOC Team",
  "logsource": {
    "product": "firewall",
    "service": "network"
  },
  "detection": {
    "selection_scan": {
      "event_type": "network_scan",
      "src_ip": "*",
      "dst_ip": "10.0.12.*",
      "rule": "Port scan detected (>100 ports in 60s)"
    },
    "selection_auth": {
      "event_type": "authentication",
      "src_ip": "10.0.12.*",
      "outcome": "success",
      "user": "*"
    },
    "condition": "selection_scan and selection_auth"
  },
  "level": "high",
  "tags": ["attack.lateral_movement", "attack.t1021"]
}
